'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var Float64Array = require( '@stdlib/array/float64' );
var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
var iteratorSymbol = require( '@stdlib/symbol/iterator' );
var iterCartesianProduct = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof iterCartesianProduct, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not an array-like object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			iterCartesianProduct( value, [ 1, 2 ] );
		};
	}
});

tape( 'the function throws an error if provided a second argument which is not an array-like object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			iterCartesianProduct( [ 1, 2 ], value );
		};
	}
});

tape( 'the function returns an iterator protocol-compliant object', function test( t ) {
	var expected;
	var actual;
	var it;
	var i;

	it = iterCartesianProduct( [ 1, 2, 3 ], [ 4, 5 ] );
	t.strictEqual( it.next.length, 0, 'has zero arity' );

	expected = [
		[ 1, 4 ],
		[ 1, 5 ],
		[ 2, 4 ],
		[ 2, 5 ],
		[ 3, 4 ],
		[ 3, 5 ]
	];
	actual = [];
	for ( i = 0; i < expected.length; i++ ) {
		actual.push( it.next().value );
	}
	t.deepEqual( actual, expected, 'returns expected values' );

	t.strictEqual( it.next().done, true, 'returns expected value' );
	t.strictEqual( it.next().done, true, 'returns expected value' );
	t.end();
});

tape( 'the function returns an empty iterator if provided an empty first array-like object', function test( t ) {
	var it;

	it = iterCartesianProduct( [], [ 1, 2 ] );
	t.strictEqual( it.next().done, true, 'returns expected value' );

	t.end();
});

tape( 'the function returns an empty iterator if provided an empty second array-like object', function test( t ) {
	var it;

	it = iterCartesianProduct( [ 1, 2 ], [] );
	t.strictEqual( it.next().done, true, 'returns expected value' );

	t.end();
});

tape( 'the function supports typed arrays', function test( t ) {
	var expected;
	var actual;
	var x1;
	var x2;
	var it;
	var i;

	x1 = new Float64Array( [ 1, 2 ] );
	x2 = new Float64Array( [ 3, 4 ] );
	it = iterCartesianProduct( x1, x2 );

	expected = [
		[ 1, 3 ],
		[ 1, 4 ],
		[ 2, 3 ],
		[ 2, 4 ]
	];
	actual = [];
	for ( i = 0; i < expected.length; i++ ) {
		actual.push( it.next().value );
	}
	t.deepEqual( actual, expected, 'returns expected values' );
	t.end();
});

tape( 'the function supports accessor arrays', function test( t ) {
	var expected;
	var actual;
	var x1;
	var x2;
	var it;
	var i;

	x1 = toAccessorArray( [ 1, 2 ] );
	x2 = toAccessorArray( [ 3, 4 ] );
	it = iterCartesianProduct( x1, x2 );

	expected = [
		[ 1, 3 ],
		[ 1, 4 ],
		[ 2, 3 ],
		[ 2, 4 ]
	];
	actual = [];
	for ( i = 0; i < expected.length; i++ ) {
		actual.push( it.next().value );
	}
	t.deepEqual( actual, expected, 'returns expected values' );
	t.end();
});

tape( 'the returned iterator has a `return` method for closing an iterator (no argument)', function test( t ) {
	var it;
	var r;

	it = iterCartesianProduct( [ 1, 2 ], [ 3, 4 ] );

	r = it.next();
	t.deepEqual( r.value, [ 1, 3 ], 'returns expected value' );
	t.strictEqual( r.done, false, 'returns expected value' );

	r = it.next();
	t.deepEqual( r.value, [ 1, 4 ], 'returns expected value' );
	t.strictEqual( r.done, false, 'returns expected value' );

	r = it.return();
	t.strictEqual( r.value, void 0, 'returns expected value' );
	t.strictEqual( r.done, true, 'returns expected value' );

	r = it.next();
	t.strictEqual( r.value, void 0, 'returns expected value' );
	t.strictEqual( r.done, true, 'returns expected value' );

	t.end();
});

tape( 'the returned iterator has a `return` method for closing an iterator (argument)', function test( t ) {
	var it;
	var r;

	it = iterCartesianProduct( [ 1, 2 ], [ 3, 4 ] );

	r = it.next();
	t.deepEqual( r.value, [ 1, 3 ], 'returns expected value' );
	t.strictEqual( r.done, false, 'returns expected value' );

	r = it.next();
	t.deepEqual( r.value, [ 1, 4 ], 'returns expected value' );
	t.strictEqual( r.done, false, 'returns expected value' );

	r = it.return( 'finished' );
	t.strictEqual( r.value, 'finished', 'returns expected value' );
	t.strictEqual( r.done, true, 'returns expected value' );

	r = it.next();
	t.strictEqual( r.value, void 0, 'returns expected value' );
	t.strictEqual( r.done, true, 'returns expected value' );

	t.end();
});

tape( 'if an environment supports `Symbol.iterator`, the returned iterator is iterable', function test( t ) {
	var iterCartesianProduct;
	var it1;
	var it2;
	var x1;
	var x2;
	var i;

	iterCartesianProduct = proxyquire( './../lib/main.js', {
		'@stdlib/symbol/iterator': '__ITERATOR_SYMBOL__'
	});

	x1 = [ 1, 2 ];
	x2 = [ 3, 4 ];
	it1 = iterCartesianProduct( x1, x2 );
	t.strictEqual( typeof it1[ '__ITERATOR_SYMBOL__' ], 'function', 'has method' );
	t.strictEqual( it1[ '__ITERATOR_SYMBOL__' ].length, 0, 'has zero arity' );

	it2 = it1[ '__ITERATOR_SYMBOL__' ]();
	t.strictEqual( typeof it2, 'object', 'returns expected value' );
	t.strictEqual( typeof it2.next, 'function', 'has method' );
	t.strictEqual( typeof it2.return, 'function', 'has method' );

	for ( i = 0; i < 4; i++ ) {
		t.deepEqual( it2.next().value, it1.next().value, 'returns expected value' );
	}
	t.end();
});

tape( 'if an environment does not support `Symbol.iterator`, the returned iterator is not "iterable"', function test( t ) {
	var iterCartesianProduct;
	var it;

	iterCartesianProduct = proxyquire( './../lib/main.js', {
		'@stdlib/symbol/iterator': false
	});

	it = iterCartesianProduct( [ 1, 2 ], [ 3, 4 ] );
	t.strictEqual( it[ iteratorSymbol ], void 0, 'does not have property' );

	t.end();
});
